from collections.abc import Callable

def total(*values: float) -> float:
    return sum(values)

def select(
    values: list[str],
    predicate: Callable[[str], bool],
) -> list[str]:
    return [value for value in values if predicate(value)]

def has_text(value: str) -> bool:
    return bool(value.strip())

print(total(2.5, 3.0, 4.5))
print(select(["Ada", "", " Lin "], has_text))
```

The checker knows the type of every repeated value and can verify the callback invocation and result.
